*, ::before, ::after { box-sizing: border-box; }
@media (prefers-reduced-motion: no-preference) {
  :root { scroll-behavior: smooth; }
}
body { margin: 0px; font-family: var(--bs-body-font-family); font-size: var(--bs-body-font-size); font-weight: var(--bs-body-font-weight); line-height: var(--bs-body-line-height); color: var(--bs-body-color); text-align: var(--bs-body-text-align); background-color: var(--bs-body-bg); text-size-adjust: 100%; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); }
hr { margin: 1rem 0px; color: inherit; border-right: 0px; border-bottom: 0px; border-left: 0px; border-image: none; border-top: var(--bs-border-width) solid; opacity: 0.25; }
h6, h5, h4, h3, h2, h1 { margin-top: 0px; margin-bottom: 0.5rem; font-weight: 500; line-height: 1.2; color: var(--bs-heading-color); }
h1 { font-size: calc(1.375rem + 1.5vw); }
@media (min-width: 1200px) {
  h1 { font-size: 2.5rem; }
}
h2 { font-size: calc(1.325rem + 0.9vw); }
@media (min-width: 1200px) {
  h2 { font-size: 2rem; }
}
h3 { font-size: calc(1.3rem + 0.6vw); }
@media (min-width: 1200px) {
  h3 { font-size: 1.75rem; }
}
h4 { font-size: calc(1.275rem + 0.3vw); }
@media (min-width: 1200px) {
  h4 { font-size: 1.5rem; }
}
h5 { font-size: 1.25rem; }
h6 { font-size: 1rem; }
p { margin-top: 0px; margin-bottom: 1rem; }
abbr[title] { text-decoration: underline dotted; cursor: help; text-decoration-skip-ink: none; }
address { margin-bottom: 1rem; font-style: normal; line-height: inherit; }
ol, ul { padding-left: 2rem; }
ol, ul, dl { margin-top: 0px; margin-bottom: 1rem; }
ol ol, ul ul, ol ul, ul ol { margin-bottom: 0px; }
dt { font-weight: 700; }
dd { margin-bottom: 0.5rem; margin-left: 0px; }
blockquote { margin: 0px 0px 1rem; }
b, strong { font-weight: bolder; }
small { font-size: 0.875em; }
mark { padding: 0.1875em; color: var(--bs-highlight-color); background-color: var(--bs-highlight-bg); }
sub, sup { position: relative; font-size: 0.75em; line-height: 0; vertical-align: baseline; }
sub { bottom: -0.25em; }
sup { top: -0.5em; }
a { color: rgba(var(--bs-link-color-rgb),var(--bs-link-opacity,1)); text-decoration: underline; }
a:hover { --bs-link-color-rgb: var(--bs-link-hover-color-rgb); }
a:not([href]):not([class]), a:not([href]):not([class]):hover { color: inherit; text-decoration: none; }
pre, code, kbd, samp { font-family: var(--bs-font-monospace); font-size: 1em; }
pre { display: block; margin-top: 0px; margin-bottom: 1rem; overflow: auto; font-size: 0.875em; }
pre code { font-size: inherit; color: inherit; word-break: normal; }
code { font-size: 0.875em; color: var(--bs-code-color); overflow-wrap: break-word; }
a > code { color: inherit; }
kbd { padding: 0.1875rem 0.375rem; font-size: 0.875em; color: var(--bs-body-bg); background-color: var(--bs-body-color); }
kbd kbd { padding: 0px; font-size: 1em; }
figure { margin: 0px 0px 1rem; }
img, svg { vertical-align: middle; }
table { caption-side: bottom; border-collapse: collapse; }
caption { padding-top: 0.5rem; padding-bottom: 0.5rem; color: var(--bs-secondary-color); text-align: left; }
th { text-align: -webkit-match-parent; }
thead, tbody, tfoot, tr, td, th { border-color: inherit; border-style: solid; border-width: 0px; }
label { display: inline-block; }
button { border-radius: 0px; }
button:focus:not(:focus-visible) { outline: 0px; }
input, button, select, optgroup, textarea { margin: 0px; font-family: inherit; font-size: inherit; line-height: inherit; }
button, select { text-transform: none; }
[role="button"] { cursor: pointer; }
select { overflow-wrap: normal; }
select:disabled { opacity: 1; }
[list]:not([type="date"]):not([type="datetime-local"]):not([type="month"]):not([type="week"]):not([type="time"])::-webkit-calendar-picker-indicator { display: none !important; }
button, [type="button"], [type="reset"], [type="submit"] { appearance: button; }
button:not(:disabled), [type="button"]:not(:disabled), [type="reset"]:not(:disabled), [type="submit"]:not(:disabled) { cursor: pointer; }
textarea { resize: vertical; }
fieldset { min-width: 0px; padding: 0px; margin: 0px; border: 0px; }
legend { float: left; width: 100%; padding: 0px; margin-bottom: 0.5rem; font-size: calc(1.275rem + 0.3vw); line-height: inherit; }
@media (min-width: 1200px) {
  legend { font-size: 1.5rem; }
}
legend + * { clear: left; }
::-webkit-datetime-edit-fields-wrapper, ::-webkit-datetime-edit-text, ::-webkit-datetime-edit-minute, ::-webkit-datetime-edit-hour-field, ::-webkit-datetime-edit-day-field, ::-webkit-datetime-edit-month-field, ::-webkit-datetime-edit-year-field { padding: 0px; }
::-webkit-inner-spin-button { height: auto; }
